 obj.ready=async function(){await this.rebuild();const names=['bg-0.png','guangbiaoa.png','guangbiaob.png','guangbiaoc.png','changtiao.png','COMBO.png','Judge-0.png'];for(let i=0;i<10;i++)names.push(`combo-${i}.png`);for(const position of ['1','2','3','4','5','6',...'ABCDEF']){const inner=/[A-F]/.test(position),note=inner?this.innerConfig('note',position):this.config('note-'+position),hit=inner?{...this.config('hit-2'),...this.innerConfig('hit',position)}:this.config('hit-'+position);for(const key of ['tex','tex2','tex3','tex4','tex5'])if(note[key])names.push(note[key]);for(const pattern of [hit.frame,hit.frame2,hit.frame3]){const name=this.animationFrame(pattern,0);if(name)names.push(name);}}if(this.config('_bg-inner').tex)names.push(this.config('_bg-inner').tex);await Promise.all([...new Set(names)].map(n=>this.frame(n)));if(root.DCPreview?.calibrateSkin)await root.DCPreview.calibrateSkin(this);return this;};
